patch -p1 <<'PATCH'
--- a/src/core/lombok/javac/handlers/HandleFieldDefaults.java
+++ b/src/core/lombok/javac/handlers/HandleFieldDefaults.java
@@ -133,7 +133,7 @@
 			break;
 		}

-		if (fd == null && (type.mods.flags & (Flags.INTERFACE | Flags.ANNOTATION)) != 0) return;
+		if (fd == null && !isClassOrEnum(typeNode)) return;

 		boolean defaultToPrivate = levelIsExplicit ? false : Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.FIELD_DEFAULTS_PRIVATE_EVERYWHERE));
 		boolean defaultToFinal = makeFinalIsExplicit ? false : Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.FIELD_DEFAULTS_FINAL_EVERYWHERE));
--- a/src/core/lombok/eclipse/handlers/HandleFieldDefaults.java
+++ b/src/core/lombok/eclipse/handlers/HandleFieldDefaults.java
@@ -165,7 +165,7 @@
 			break;
 		}

-		if (fd == null && (type.modifiers & (ClassFileConstants.AccInterface | ClassFileConstants.AccAnnotation)) != 0) return;
+		if (fd == null && !isClassOrEnum(typeNode)) return;

 		boolean defaultToPrivate = levelIsExplicit ? false : Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.FIELD_DEFAULTS_PRIVATE_EVERYWHERE));
 		boolean defaultToFinal = makeFinalIsExplicit ? false : Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.FIELD_DEFAULTS_FINAL_EVERYWHERE));
--- a/website/templates/features/experimental/FieldDefaults.html
+++ b/website/templates/features/experimental/FieldDefaults.html
@@ -49,6 +49,9 @@
 	</@f.confKeys>

 	<@f.smallPrint>
+		<p>
+			The <code>lombok.fieldDefaults.defaultPrivate</code> and <code>lombok.fieldDefaults.defaultFinal</code> configuration keys are ignored for records. Explicit use of <code>@FieldDefaults</code> on a record is not supported.
+		</p>
 		<p>
 			Like other lombok handlers that touch fields, any field whose name starts with a dollar (<code>$</code>) symbol is skipped entirely. Such a field will not be modified at all.
 		</p>
PATCH
ant test.compile && ant test.javacCurrent > /testbed/build/field-defaults-after.log 2>&1; result=$?; grep -E '\[(FAIL|PASS)\].*FieldDefaults|\[FAIL\]' /testbed/build/field-defaults-after.log; tail -5 /testbed/build/field-defaults-after.log; exit "$result"

